import React, { useState } from 'react';
import { motion } from 'framer-motion';
import { useInView } from '../../hooks/useAnimations';
import SectionHeader from '../ui/SectionHeader';
import { Mail, Github, Linkedin, ArrowUpRight, Send, CheckCircle, AlertCircle, Loader2 } from 'lucide-react';

const BACKEND_URL = process.env.REACT_APP_BACKEND_URL;

const ContactFooter = () => {
  const [ref, isInView] = useInView({ threshold: 0.1 });
  const [formData, setFormData] = useState({ name: '', email: '', subject: '', message: '' });
  const [status, setStatus] = useState(null); // null | 'sending' | 'success' | 'error'
  const [errorMsg, setErrorMsg] = useState('');

  const handleChange = (e) => {
    setFormData({ ...formData, [e.target.name]: e.target.value });
  };

  const handleSubmit = async (e) => {
    e.preventDefault();
    setStatus('sending');
    setErrorMsg('');

    try {
      const res = await fetch(`${BACKEND_URL}/api/contact`, {
        method: 'POST',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify(formData),
      });

      if (!res.ok) throw new Error('Failed to send message');
      setStatus('success');
      setFormData({ name: '', email: '', subject: '', message: '' });
      setTimeout(() => setStatus(null), 5000);
    } catch (err) {
      setStatus('error');
      setErrorMsg('Something went wrong. Please try again.');
      setTimeout(() => setStatus(null), 4000);
    }
  };

  return (
    <footer id="contact" data-testid="contact-section" className="relative py-32 pb-16">
      <div className="max-w-7xl mx-auto px-6 md:px-12">
        <SectionHeader number="08" title="Contact" />

        <div ref={ref} className="grid grid-cols-1 lg:grid-cols-2 gap-16">
          {/* Left side - Info */}
          <div>
            <motion.h2
              className="font-heading font-extrabold text-4xl sm:text-5xl md:text-6xl text-white mb-6 tracking-tight leading-[1.1]"
              initial={{ opacity: 0, y: 30 }}
              animate={isInView ? { opacity: 1, y: 0 } : {}}
              transition={{ duration: 0.8 }}
              data-testid="contact-headline"
            >
              Let's Build
              <br />
              <span className="bg-gradient-to-r from-accent via-accent/80 to-teal-300 bg-clip-text text-transparent">
                Something Great
              </span>
            </motion.h2>

            <motion.p
              className="text-lg text-slate-400 mb-10 max-w-lg"
              initial={{ opacity: 0, y: 20 }}
              animate={isInView ? { opacity: 1, y: 0 } : {}}
              transition={{ duration: 0.7, delay: 0.2 }}
              data-testid="contact-subtext"
            >
              Building something interesting? I'd love to hear about it.
              Drop me a message and I'll get back to you soon.
            </motion.p>

            {/* Social Links */}
            <motion.div
              className="flex flex-col gap-3"
              initial={{ opacity: 0, y: 20 }}
              animate={isInView ? { opacity: 1, y: 0 } : {}}
              transition={{ duration: 0.7, delay: 0.3 }}
            >
              <a
                href="mailto:vineet.vora123@gmail.com"
                data-testid="contact-email"
                className="group flex items-center gap-3 px-5 py-3.5 glass-card rounded-xl hover:border-accent/20 transition-all duration-300 hoverable"
              >
                <Mail size={18} className="text-accent" />
                <span className="text-white font-mono text-sm">vineet.vora123@gmail.com</span>
                <ArrowUpRight size={14} className="text-slate-500 group-hover:text-accent group-hover:translate-x-0.5 group-hover:-translate-y-0.5 transition-all ml-auto" />
              </a>

              <a
                href="https://www.linkedin.com/in/vineetv2/"
                target="_blank"
                rel="noreferrer"
                data-testid="contact-linkedin"
                className="group flex items-center gap-3 px-5 py-3.5 glass-card rounded-xl hover:border-accent/20 transition-all duration-300 hoverable"
              >
                <Linkedin size={18} className="text-[#0A66C2]" />
                <span className="text-white font-mono text-sm">LinkedIn</span>
                <ArrowUpRight size={14} className="text-slate-500 group-hover:text-accent group-hover:translate-x-0.5 group-hover:-translate-y-0.5 transition-all ml-auto" />
              </a>

              <a
                href="https://github.com/VineetV2"
                target="_blank"
                rel="noreferrer"
                data-testid="contact-github"
                className="group flex items-center gap-3 px-5 py-3.5 glass-card rounded-xl hover:border-accent/20 transition-all duration-300 hoverable"
              >
                <Github size={18} className="text-white" />
                <span className="text-white font-mono text-sm">GitHub</span>
                <ArrowUpRight size={14} className="text-slate-500 group-hover:text-accent group-hover:translate-x-0.5 group-hover:-translate-y-0.5 transition-all ml-auto" />
              </a>
            </motion.div>
          </div>

          {/* Right side - Form */}
          <motion.div
            initial={{ opacity: 0, y: 30 }}
            animate={isInView ? { opacity: 1, y: 0 } : {}}
            transition={{ duration: 0.8, delay: 0.3 }}
          >
            <form onSubmit={handleSubmit} data-testid="contact-form" className="space-y-5">
              <div className="grid grid-cols-1 sm:grid-cols-2 gap-5">
                <div>
                  <label htmlFor="name" className="block font-mono text-xs text-slate-500 tracking-wide uppercase mb-2">
                    Name *
                  </label>
                  <input
                    type="text"
                    id="name"
                    name="name"
                    required
                    value={formData.name}
                    onChange={handleChange}
                    data-testid="contact-form-name"
                    className="w-full px-4 py-3 bg-void-50 border border-white/[0.06] rounded-xl text-white text-sm font-body placeholder-slate-600 focus:outline-none focus:border-accent/40 focus:ring-1 focus:ring-accent/20 transition-all"
                    placeholder="Your name"
                  />
                </div>
                <div>
                  <label htmlFor="email" className="block font-mono text-xs text-slate-500 tracking-wide uppercase mb-2">
                    Email *
                  </label>
                  <input
                    type="email"
                    id="email"
                    name="email"
                    required
                    value={formData.email}
                    onChange={handleChange}
                    data-testid="contact-form-email"
                    className="w-full px-4 py-3 bg-void-50 border border-white/[0.06] rounded-xl text-white text-sm font-body placeholder-slate-600 focus:outline-none focus:border-accent/40 focus:ring-1 focus:ring-accent/20 transition-all"
                    placeholder="you@example.com"
                  />
                </div>
              </div>

              <div>
                <label htmlFor="subject" className="block font-mono text-xs text-slate-500 tracking-wide uppercase mb-2">
                  Subject
                </label>
                <input
                  type="text"
                  id="subject"
                  name="subject"
                  value={formData.subject}
                  onChange={handleChange}
                  data-testid="contact-form-subject"
                  className="w-full px-4 py-3 bg-void-50 border border-white/[0.06] rounded-xl text-white text-sm font-body placeholder-slate-600 focus:outline-none focus:border-accent/40 focus:ring-1 focus:ring-accent/20 transition-all"
                  placeholder="What's this about?"
                />
              </div>

              <div>
                <label htmlFor="message" className="block font-mono text-xs text-slate-500 tracking-wide uppercase mb-2">
                  Message *
                </label>
                <textarea
                  id="message"
                  name="message"
                  required
                  rows={5}
                  value={formData.message}
                  onChange={handleChange}
                  data-testid="contact-form-message"
                  className="w-full px-4 py-3 bg-void-50 border border-white/[0.06] rounded-xl text-white text-sm font-body placeholder-slate-600 focus:outline-none focus:border-accent/40 focus:ring-1 focus:ring-accent/20 transition-all resize-none"
                  placeholder="Tell me about your project, idea, or just say hi..."
                />
              </div>

              {/* Submit button */}
              <button
                type="submit"
                disabled={status === 'sending'}
                data-testid="contact-form-submit"
                className="group w-full px-6 py-3.5 bg-accent text-void font-heading font-semibold text-sm tracking-wide rounded-xl hover:shadow-[0_0_30px_rgba(14,246,204,0.3)] transition-all duration-300 flex items-center justify-center gap-2 disabled:opacity-50 disabled:cursor-not-allowed hoverable"
              >
                {status === 'sending' ? (
                  <>
                    <Loader2 size={16} className="animate-spin" />
                    Sending...
                  </>
                ) : (
                  <>
                    Send Message
                    <Send size={16} className="group-hover:translate-x-1 transition-transform" />
                  </>
                )}
              </button>

              {/* Status messages */}
              {status === 'success' && (
                <motion.div
                  initial={{ opacity: 0, y: 10 }}
                  animate={{ opacity: 1, y: 0 }}
                  className="flex items-center gap-2 p-4 rounded-xl bg-accent/[0.08] border border-accent/20"
                  data-testid="contact-form-success"
                >
                  <CheckCircle size={18} className="text-accent shrink-0" />
                  <p className="text-sm text-accent">Message sent successfully! I'll get back to you soon.</p>
                </motion.div>
              )}

              {status === 'error' && (
                <motion.div
                  initial={{ opacity: 0, y: 10 }}
                  animate={{ opacity: 1, y: 0 }}
                  className="flex items-center gap-2 p-4 rounded-xl bg-red-500/[0.08] border border-red-500/20"
                  data-testid="contact-form-error"
                >
                  <AlertCircle size={18} className="text-red-400 shrink-0" />
                  <p className="text-sm text-red-400">{errorMsg}</p>
                </motion.div>
              )}
            </form>
          </motion.div>
        </div>

        {/* Footer bottom */}
        <motion.div
          className="border-t border-white/[0.04] pt-8 mt-20 flex flex-col sm:flex-row items-center justify-between gap-4"
          initial={{ opacity: 0 }}
          animate={isInView ? { opacity: 1 } : {}}
          transition={{ duration: 0.8, delay: 0.5 }}
        >
          <p className="text-sm text-slate-500 font-mono" data-testid="footer-copyright">
            &copy; {new Date().getFullYear()} Vineet Vora. Crafted with precision.
          </p>
          <p className="text-xs text-slate-600 font-mono" data-testid="footer-tagline">
            Built with React + Framer Motion + Tailwind
          </p>
        </motion.div>
      </div>
    </footer>
  );
};

export default ContactFooter;
